<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useAuthStore} from '../../stores/auth'
import {ApiError} from '../../api/auth'
import {askQuestion,questions,questionOperation,type QuestionInput,type QuestionAttempt,type QuestionList,type QuestionAnswer} from '../../api/questions'
import {normalizeQuestion,savePending,readPending,removePending} from '../../stores/questionRecovery'
const props=defineProps<{analysisId:string;instrumentId:string}>()
const auth=useAuthStore(),input=ref(''),pending=ref<QuestionInput|null>(null),attempt=ref<QuestionAttempt|null>(null),view=ref<QuestionList|null>(null),selected=ref(''),page=ref(1),busy=ref(false),error=ref('')
let generation=0
const answer=computed(()=>view.value?.items.find(a=>a.answerId===selected.value)||view.value?.items[0]||null)
const size=computed(()=>[...input.value].length)
const suggestions=[{id:'indicator',text:'MA、MACD、RSI分别说明什么？'},{id:'prediction',text:'为什么预测走势向上，但部分价格低于原点收盘价？'},{id:'risk',text:'这份分析有哪些风险？'},{id:'verification',text:'这次预测有没有实际数据验证？'}]
function apply(a:QuestionAttempt){attempt.value=a;if(a.state==='RUNNING'){if(!pending.value){pending.value={operationId:a.operationId,analysisId:a.analysisId,question:a.question};input.value=a.question;if(auth.profile)savePending(auth.profile.userId,pending.value)}}else if(pending.value?.operationId===a.operationId){if(auth.profile)removePending(auth.profile.userId,pending.value.analysisId);pending.value=null}}
async function load(turn=generation){const data=await questions(props.analysisId,page.value);if(turn!==generation)return;view.value=data;if(!data.items.some(a=>a.answerId===selected.value))selected.value=data.items[0]?.answerId||'';if(data.latestAttempt&&(!pending.value||pending.value.operationId===data.latestAttempt.operationId))apply(data.latestAttempt)}
async function refresh(){if(busy.value||!auth.profile)return;const turn=generation;busy.value=true;error.value='';try{if(pending.value){try{const a=await questionOperation(pending.value.operationId);if(turn!==generation)return;apply(a)}catch(e){if(turn!==generation)return;if((e as {status?:number}).status!==404)throw e;error.value='原请求暂未查到，可明确恢复原请求；不会自动创建新请求。'}}await load(turn)}catch(e){if(turn===generation)error.value=(e as Error).message||'查询未完成'}finally{if(turn===generation)busy.value=false}}
async function send(recover=false){if(busy.value||!auth.profile||!props.analysisId)return;const turn=generation;let request:QuestionInput;try{if(recover&&pending.value)request=pending.value;else{if(pending.value)return;request={operationId:crypto.randomUUID(),analysisId:props.analysisId,question:normalizeQuestion(input.value)};savePending(auth.profile.userId,request);pending.value=request;input.value=request.question}}catch(e){error.value=(e as Error).message;return}busy.value=true;error.value='';try{const a=await askQuestion(request);if(turn!==generation)return;apply(a);if(a.state==='SUCCEEDED'){page.value=1;selected.value=''}await load(turn)}catch(e){if(turn===generation){error.value=(e as Error).message||'请求未完成';if(!recover&&e instanceof ApiError&&['AI_BUSY','AI_REQUEST_INVALID','AI_REQUEST_TOO_LARGE','AI_NOT_CONFIGURED','QUESTION_EVIDENCE_INVALID'].includes(e.code)){removePending(auth.profile.userId,request.analysisId);pending.value=null}}}finally{if(turn===generation)busy.value=false}}
async function move(delta:number){if(pending.value||busy.value)return;page.value+=delta;await refresh()}
watch(()=>[props.analysisId,props.instrumentId,auth.profile?.userId],()=>{++generation;pending.value=null;attempt.value=null;view.value=null;selected.value='';input.value='';page.value=1;busy.value=false;error.value='';if(!auth.profile)return;try{pending.value=readPending(auth.profile.userId,props.analysisId);if(pending.value)input.value=pending.value.question}catch(e){error.value=(e as Error).message;return}void refresh();},{immediate:true})
onBeforeUnmount(()=>{generation++})
const titles:Record<string,string>={overview:'回答',readout:'依据说明',risk:'限制与提醒'}
function when(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}
</script>
<template><section class="question-panel" aria-label="有依据的AI问答"><div class="heading"><h3>继续问AI</h3><button data-testid="refresh-questions" :disabled="busy||!auth.profile" @click="refresh">刷新问答记录</button></div><p class="hint">围绕当前这份已保存分析提问。每次独立回答，依据不会自动变成最新行情；点击发送才调用AI。</p><div class="suggestions"><button v-for="s in suggestions" :key="s.id" :data-testid="'question-suggestion-'+s.id" :disabled="busy||!!pending" @click="input=s.text">{{s.text}}</button></div><label>你的问题<textarea data-testid="question-input" v-model="input" :disabled="busy||!!pending" rows="3" placeholder="询问指标、预测、风险或验证情况，请勿填写密码或密钥。" /></label><div class="actions"><span>{{size}} / 300字</span><button v-if="!pending" data-testid="send-question" class="primary" :disabled="busy||!auth.profile||!input||view?.configured===false" @click="send()">{{busy?'正在回答…':'发送问题'}}</button><template v-else><button :disabled="busy" @click="refresh">查询原请求</button><button data-testid="recover-question" :disabled="busy" @click="send(true)">{{attempt?.expired?'结束过期请求':'恢复原请求'}}</button></template></div><p v-if="pending" role="status">{{attempt?.expired?'原请求已过期，请明确结束后再发送新问题。':'原请求尚未确认，已保留原问题和编号；恢复原请求不会另建编号。'}}</p><p v-if="attempt?.state==='FAILED'" role="status">上次回答未完成，原分析与已有回答保留。原因：{{attempt.errorCode}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="view?.configured===false" class="hint">问答未配置，已保存记录仍可查看。</p><template v-if="answer"><label v-if="view&&view.items.length>1">已保存问题<select v-model="selected"><option v-for="a in view.items" :key="a.answerId" :value="a.answerId">{{a.question}} · {{when(a.createdAt)}}</option></select></label><article><h4>{{answer.question}}</h4><p class="hint">回答时间：{{when(answer.createdAt)}} · 依据截至：{{answer.context.facts.AS_OF}}</p><p v-if="answer.status==='OUT_OF_SCOPE'">这个问题超出当前资料范围，或所选分析未引用所需预测。可以询问本股已保存指标、风险及已有预测验证情况。</p><section v-for="p in answer.paragraphs" :key="p.kind"><h5>{{titles[p.kind]||p.kind}}</h5><p>{{p.text}}</p></section><details><summary>查看回答依据</summary><p v-for="p in answer.paragraphs" :key="p.kind">{{titles[p.kind]||p.kind}}引用：{{p.refs.join('、')}}</p><dl><dt>源分析／保存时间</dt><dd>{{answer.context.sourceAnalysisId}} ／ {{answer.context.sourceCreatedAt}}</dd><dt>问答提示／知识版本／文本模型</dt><dd>{{answer.context.promptVersion}} ／ {{answer.context.knowledgeVersion}} ／ {{answer.context.providerModel}}</dd><template v-if="answer.context.sourceContext?.prediction"><dt>预测原点／生成时验证版本</dt><dd>{{answer.context.sourceContext.prediction.originDate}} ／ {{answer.context.sourceContext.prediction.verificationVersionId||'尚无有效验证版本'}}</dd></template><template v-for="(value,key) in answer.context.facts" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></details></article></template><p v-else-if="!busy&&!pending" class="hint">还没有这份分析的问答记录。</p><div v-if="view&&view.total>10" class="actions"><button :disabled="busy||!!pending||page===1" @click="move(-1)">上一页</button><span>第{{page}}页</span><button :disabled="busy||!!pending||page*10>=view.total" @click="move(1)">下一页</button></div></section></template>
<style scoped>.question-panel{margin-top:24px;padding-top:24px;border-top:1px solid var(--border)}.heading,.actions,.suggestions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.heading{justify-content:space-between}.actions{justify-content:flex-end;margin:12px 0}.suggestions{margin:16px 0}.hint,small,dd{color:var(--muted)}label{display:flex;flex-direction:column;gap:8px}textarea,select{width:100%;box-sizing:border-box;font:inherit;color:var(--ink);background:white;border:1px solid var(--border);border-radius:8px;padding:12px}button{font:inherit;min-height:44px;padding:10px 14px;border:1px solid var(--border);border-radius:8px;background:white;color:var(--ink);cursor:pointer}.primary{background:var(--accent);color:white}button:disabled,textarea:disabled{opacity:.6;cursor:default}button:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}p{line-height:1.7;overflow-wrap:anywhere}article{margin-top:20px;padding:18px;border:1px solid var(--border);border-radius:10px;background:white}h4{font-size:17px;margin-top:0}h5{font-size:16px;margin-bottom:0}summary{cursor:pointer;min-height:44px;padding-top:14px}dd{margin:4px 0 12px;overflow-wrap:anywhere}</style>
